import{_ as i,o as n,c as r,a2 as t}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Zivilisation des pluralistischen Typs Nordamerikas","description":"","frontmatter":{},"headers":[],"relativePath":"de/33-北美多元型文明.md","filePath":"de/33-北美多元型文明.md"}'),s={name:"de/33-北美多元型文明.md"};function l(a,e,u,d,o,h){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="zivilisation-des-pluralistischen-typs-nordamerikas" tabindex="-1">Zivilisation des pluralistischen Typs Nordamerikas <a class="header-anchor" href="#zivilisation-des-pluralistischen-typs-nordamerikas" aria-label="Permalink to &quot;Zivilisation des pluralistischen Typs Nordamerikas&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>33</td></tr><tr><td>Modul</td><td>Zivilisationstypologie und Sozialsystem</td></tr><tr><td>Schlüsselwörter</td><td>Pluralistisch Nordamerika, Freier Wettbewerb, Chancengleichheit, Innovationsdynamik, Marktmechanismus</td></tr></tbody></table><h2 id="i-ursprung-und-kernphilosophie-der-zivilisation-des-pluralistischen-typs-nordamerikas" tabindex="-1">I. Ursprung und Kernphilosophie der Zivilisation des pluralistischen Typs Nordamerikas <a class="header-anchor" href="#i-ursprung-und-kernphilosophie-der-zivilisation-des-pluralistischen-typs-nordamerikas" aria-label="Permalink to &quot;I. Ursprung und Kernphilosophie der Zivilisation des pluralistischen Typs Nordamerikas&quot;">​</a></h2><p>Die Zivilisation des pluralistischen Typs Nordamerikas ist die am stärksten liberal und pluralistisch gefärbte unter den fünf Typen der symbiotischen Zivilisation, und ihr Ursprung lässt sich auf das Sozialmodell der nordamerikanischen Region (hauptsächlich USA und Kanada) in der realen Welt zurückverfolgen. Die nordamerikanische Region hat als Einwanderungsgesellschaft zivilisatorische Merkmale gebildet, die sich auf Freiheit, Pluralismus, Wettbewerb und Innovation konzentrieren. Nach der Gründung der symbiotischen Ankerzivilisation wurde diese Tradition mit der symbiotischen Philosophie verbunden, um die einzigartige Zivilisationsform der „Zivilisation des pluralistischen Typs Nordamerikas&quot; zu schaffen.</p><p>Die Kernphilosophie der Zivilisation des pluralistischen Typs Nordamerikas lässt sich in acht Zeichen zusammenfassen: „freiheitlicher Pluralismus, Chancengleichheit&quot;. Im Einzelnen:</p><ol><li><strong>Freiheitlicher Pluralismus</strong>: Betont die individuelle Freiheit und den kulturellen Pluralismus. Jedes Individuum hat das Recht, seinen eigenen Lebensstil, seine Kultivierungsrichtung und seine Wertverfolgung zu wählen, und die Gesellschaft respektiert und akzeptiert diese Vielfalt</li><li><strong>Chancengleichheit</strong>: Betont, dass jedes Individuum gleiche Chancen auf Erfolg haben sollte, garantiert aber keine Gleichheit der Ergebnisse. Die Gesellschaft gewährleistet Chancengleichheit durch die Beseitigung von Diskriminierung, die Bereitstellung von Grundbildung usw., aber der endgültige Erfolg hängt von der Anstrengung und dem Talent des Individuums ab</li><li><strong>Marktwettbewerb</strong>: Glaubt, dass der Marktwettbewerb die effektivste Methode zur Allokation von Ressourcen ist. Durch freien Wettbewerb können exzellente Kultivierer und Organisationen hervorstechen, und Ressourcen können an die effizientesten Orte fließen</li><li><strong>Innovationsgetrieben</strong>: Ermutigt Innovation und Risikobereitschaft und glaubt, dass Innovation die zentrale Triebkraft ist, die den Fortschritt der Zivilisation vorantreibt. Die Gesellschaft hat eine tolerante Einstellung gegenüber Misserfolgen und ermutigt die Menschen, neue Dinge mutig auszuprobieren</li></ol><p>Diese Philosophien der Zivilisation des pluralistischen Typs Nordamerikas高度 stimmen mit der Kernphilosophie der symbiotischen Ankerzivilisation überein: „sich selbst erzeugen und wachsen&quot;. Der freiheitliche Pluralismus gewährleistet das Recht auf autonome Wahl des Individuums, die Chancengleichheit gewährleistet die Gerechtigkeit des Ausgangspunkts von „jeder hat einen Weg&quot;, und Marktwettbewerb sowie innovationsgetrieben sind die lebendige Manifestation von „sich selbst erzeugen und wachsen&quot;.</p><h2 id="ii-sozialstruktur-der-zivilisation-des-pluralistischen-typs-nordamerikas" tabindex="-1">II. Sozialstruktur der Zivilisation des pluralistischen Typs Nordamerikas <a class="header-anchor" href="#ii-sozialstruktur-der-zivilisation-des-pluralistischen-typs-nordamerikas" aria-label="Permalink to &quot;II. Sozialstruktur der Zivilisation des pluralistischen Typs Nordamerikas&quot;">​</a></h2><p>Die Sozialstruktur der Zivilisation des pluralistischen Typs Nordamerikas zeichnet sich durch „kleine Regierung, große Gesellschaft, starker Markt, multikulturell&quot; aus:</p><table tabindex="0"><thead><tr><th>Strukturelement</th><th>Merkmalsbeschreibung</th><th>Kernfunktion</th></tr></thead><tbody><tr><td>Begrenzte Regierung</td><td>Die Regierung hat einen kleinen Umfang, begrenzte Funktionen und ist hauptsächlich für die Aufrechterhaltung der Ordnung und die Bereitstellung grundlegender öffentlicher Dienstleistungen verantwortlich</td><td>Gewährleistung der marktwettbewerblichen Umgebung, Bereitstellung grundlegender öffentlicher Dienstleistungen</td></tr><tr><td>Starker Markt</td><td>Der Marktmechanismus spielt eine entscheidende Rolle bei der Ressourcenallokation</td><td>Effiziente Allokation von Kultivierungsressourcen, Förderung von Innovation und Wettbewerb</td></tr><tr><td>Multikulturell</td><td>Mehrere Kulturen, mehrere Werte, mehrere Lebensstile koexistieren</td><td>Bereicherung des Zivilisationsökosystems, Stimulierung der Innovationsdynamik</td></tr><tr><td>Zivilgesellschaft</td><td>Nichtregierungsorganisationen, Gemeinschaftsorganisationen, Freiwilligenorganisationen sind entwickelt</td><td>Ergänzung der Mängel von Regierung und Markt, Lösung sozialer Probleme</td></tr></tbody></table><h3 id="_2-1-begrenzte-regierung" tabindex="-1">2.1 Begrenzte Regierung <a class="header-anchor" href="#_2-1-begrenzte-regierung" aria-label="Permalink to &quot;2.1 Begrenzte Regierung&quot;">​</a></h3><p>Die Zivilisation des pluralistischen Typs Nordamerikas glaubt, dass „die Regierung, die am wenigsten regiert, die beste Regierung ist&quot;. Die Funktionen der Regierung sind streng auf folgende Bereiche beschränkt:</p><ul><li>Aufrechterhaltung der sozialen Ordnung und Rechtsdurchsetzung</li><li>Bereitstellung grundlegender öffentlicher Dienstleistungen (wie grundlegende Infrastruktur, öffentliche Sicherheit)</li><li>Gewährleistung grundlegender Wohlfahrt (wie Mindestlebenssicherung, grundlegende Gesundheitsversorgung)</li><li>Aufrechterhaltung der Marktordnungsordnung (wie Kartellverbot, Verbraucherschutz)</li></ul><p>Die Regierung greift nicht direkt in Angelegenheiten wie die Allokation von Kultivierungsressourcen, die Wahl des Kultivierungssystems, die persönliche Entwicklung der Kultivierer usw. ein, und diese werden autonom von Markt und Individuum entschieden. Diese Philosophie der „begrenzten Regierung&quot; gewährleistet in maximalem Maße die individuelle Freiheit und die Marktdynamik.</p><h3 id="_2-2-starker-markt" tabindex="-1">2.2 Starker Markt <a class="header-anchor" href="#_2-2-starker-markt" aria-label="Permalink to &quot;2.2 Starker Markt&quot;">​</a></h3><p>Der Marktmechanismus spielt eine zentrale Rolle in der Zivilisation des pluralistischen Typs Nordamerikas. Die Allokation von Kultivierungsressourcen, die Bereitstellung von Kultivierungsdienstleistungen, die Mobilität von Kultivierungstalenten usw. werden hauptsächlich durch den Marktmechanismus durchgeführt:</p><ul><li><strong>Markt für Kultivierungsressourcen</strong>: Verschiedene Arten von Kultivierungsressourcen (Energie, Pillen, Schätze, Methoden usw.) werden frei auf dem Markt gehandelt, und die Preise werden durch das Angebot-Nachfrage-Verhältnis bestimmt</li><li><strong>Markt für Kultivierungsdienstleistungen</strong>: Dienstleistungen wie Mentorenanleitung, Kultivierungstraining, Kultivierungsberatung werden auf marktwirtschaftliche Weise bereitgestellt</li><li><strong>Markt für Kultivierungstalente</strong>: Kultivierungstalente fließen frei durch den Marktmechanismus und wählen die für sie am besten geeignete Entwicklungsplattform</li><li><strong>Markt für Kultivierungstechnologie</strong>: Forschung und Entwicklung, Transfer und Anwendung von Kultivierungstechnologie werden auf marktwirtschaftliche Weise betrieben</li></ul><p>Der starke Marktmechanismus bringt hohe Effizienz und hohe Dynamik, erfordert aber auch, dass die Regierung durch Kartellverbot, Verbraucherschutzgesetze usw. reguliert, um Marktversagen zu verhindern.</p><h3 id="_2-3-multikulturell" tabindex="-1">2.3 Multikulturell <a class="header-anchor" href="#_2-3-multikulturell" aria-label="Permalink to &quot;2.3 Multikulturell&quot;">​</a></h3><p>Die Zivilisation des pluralistischen Typs Nordamerikas ist ein Schmelztiegel der Kulturen, und Wesen verschiedener Rassen, verschiedener Ebenen, verschiedener kultureller Hintergründe koexistieren hier. Der Multikulturalismus manifestiert sich in:</p><ul><li>Mehrere Kultivierungssysteme koexistieren, und die Kultivierer können frei wählen</li><li>Mehrere Lebensstile koexistieren, und die Gesellschaft respektiert unterschiedliche Wertentscheidungen</li><li>Mehrere Sprachen und Schriften koexistieren, und der kulturelle Austausch ist bunt</li><li>Mehrere religiöse Überzeugungen koexistieren, und die Religionsfreiheit ist geschützt</li></ul><p>Der Multikulturalismus bringt der Zivilisation reiche Kreativität und Innovationsdynamik. Der Zusammenstoß und die Verschmelzung verschiedener Kulturen können oft neue Ideen und neue Technologien hervorbringen.</p><h3 id="_2-4-zivilgesellschaft" tabindex="-1">2.4 Zivilgesellschaft <a class="header-anchor" href="#_2-4-zivilgesellschaft" aria-label="Permalink to &quot;2.4 Zivilgesellschaft&quot;">​</a></h3><p>Die Zivilisation des pluralistischen Typs Nordamerikas verfügt über eine entwickelte Zivilgesellschaft, und Nichtregierungsorganisationen, Gemeinschaftsorganisationen, Freiwilligenorganisationen spielen eine wichtige Rolle im gesellschaftlichen Leben:</p><ul><li><strong>Gemeinnützige Wohlfahrtsorganisationen</strong>: Gegründet durch Spenden von Wohlhabenden, engagiert sich in gemeinnützigen Angelegenheiten wie Armutsbekämpfung, Bildung, Gesundheit</li><li><strong>Gemeinschaftliche Selbstverwaltungsorganisationen</strong>: Freiwillig von Gemeindebwohnern gegründet, verwalten die öffentlichen Angelegenheiten der Gemeinde</li><li><strong>Branchenverbände</strong>: Von Kultivierern und Organisationen derselben Branche gegründet, formulieren Branchenstandards, wahren die Interessen der Branche</li><li><strong>Freiwilligenorganisationen</strong>: Von Freiwilligen gegründet, engagiert sich in verschiedenen sozialen Dienstleistungen</li></ul><p>Die Zivilgesellschaft ergänzt die Mängel von Regierung und Markt und bietet der Gesellschaft vielfältige Dienstleistungen und Lösungen.</p><h2 id="iii-kultivierungsmodell-der-zivilisation-des-pluralistischen-typs-nordamerikas" tabindex="-1">III. Kultivierungsmodell der Zivilisation des pluralistischen Typs Nordamerikas <a class="header-anchor" href="#iii-kultivierungsmodell-der-zivilisation-des-pluralistischen-typs-nordamerikas" aria-label="Permalink to &quot;III. Kultivierungsmodell der Zivilisation des pluralistischen Typs Nordamerikas&quot;">​</a></h2><p>Das Kultivierungsmodell der Zivilisation des pluralistischen Typs Nordamerikas zeichnet sich durch „autonome Wahl, wettbewerbsorientierte Auswahl, innovationsgetrieben&quot; aus:</p><h3 id="_3-1-autonome-wahl" tabindex="-1">3.1 Autonome Wahl <a class="header-anchor" href="#_3-1-autonome-wahl" aria-label="Permalink to &quot;3.1 Autonome Wahl&quot;">​</a></h3><p>Die Kultivierer der Zivilisation des pluralistischen Typs Nordamerikas besitzen ein sehr großes Recht auf autonome Wahl:</p><ul><li>Können frei das Kultivierungssystem wählen, ohne jeglichen Zwang</li><li>Können frei den Kultivierungsmentor und die Kultivierungsinstitution wählen</li><li>Können frei die Kultivierungszeit und den Kultivierungsrhythmus arrangieren</li><li>Können frei die Kultivierungsrichtung und den Entwicklungsweg wechseln</li></ul><p>Diese autonome Wahl ermöglicht es den Kultivierern, den für sie am besten geeigneten Entwicklungsweg entsprechend ihren eigenen Interessen und Eigenschaften zu finden.</p><h3 id="_3-2-wettbewerbsorientierte-auswahl" tabindex="-1">3.2 Wettbewerbsorientierte Auswahl <a class="header-anchor" href="#_3-2-wettbewerbsorientierte-auswahl" aria-label="Permalink to &quot;3.2 Wettbewerbsorientierte Auswahl&quot;">​</a></h3><p>Das Kultivierungsfeld der Zivilisation des pluralistischen Typs Nordamerikas ist voller Wettbewerb:</p><ul><li>Kultivierer erhalten durch Wettbewerb Fortschrittsressourcen und Anleitung von hochrangigen Mentoren</li><li>Kultivierungsinstitutionen ziehen durch Wettbewerb exzellente Lernende und hochwertige Ressourcen an</li><li>Kultivierungstechnologien erhalten durch Wettbewerb Marktanerkennung und Anwendungsförderung</li></ul><p>Der Mechanismus der wettbewerbsorientierten Auswahl ermöglicht es den exzellentesten Talenten und den effektivsten Technologien, hervorzustechen, und Ressourcen können an die effizientesten Orte fließen. Aber gleichzeitig bietet die Gesellschaft auch eine grundlegende Garantie für die Verlierer im Wettbewerb, um sicherzustellen, dass sie aufgrund des Misserfolgs nicht die grundlegenden Überlebens- und Evolutionsrechte verlieren.</p><h3 id="_3-3-innovationsgetrieben" tabindex="-1">3.3 Innovationsgetrieben <a class="header-anchor" href="#_3-3-innovationsgetrieben" aria-label="Permalink to &quot;3.3 Innovationsgetrieben&quot;">​</a></h3><p>Die Zivilisation des pluralistischen Typs Nordamerikas legt großen Wert auf die Innovation im Kultivierungsbereich:</p><ul><li>Ermutigt Kultivierer, neue Kultivierungsmethoden und -wege zu erforschen</li><li>Bietet finanzielle Unterstützung und politische Anreize für die Innovation der Kultivierungstechnologie</li><li>Etabliert ein vollständiges System zum Schutz des geistigen Eigentums im Kultivierungsbereich</li><li>Hat eine tolerante Einstellung gegenüber Innovationsmisserfolgen und ermutigt zum „immer wieder Versuchen trotz wiederholter Misserfolge&quot;</li></ul><p>Diese innovationsgetriebene Kultur hat die Zivilisation des pluralistischen Typs Nordamerikas zu einem fruchtbaren Boden für die Innovation der Kultivierungstechnologie gemacht, und hier entstehen ständig neue Kultivierungsmethoden und -technologien.</p><h3 id="_3-4-koexistenz-von-elitenbildung-und-massenbildung" tabindex="-1">3.4 Koexistenz von Elitenbildung und Massenbildung <a class="header-anchor" href="#_3-4-koexistenz-von-elitenbildung-und-massenbildung" aria-label="Permalink to &quot;3.4 Koexistenz von Elitenbildung und Massenbildung&quot;">​</a></h3><p>Die Kultivierungsbildung der Zivilisation des pluralistischen Typs Nordamerikas weist ein Muster der „Koexistenz von Elitenbildung und Massenbildung&quot; auf:</p><ul><li><strong>Massenbildung</strong>: Die Regierung bietet kostenlose grundlegende Kultivierungsbildung an und gewährleistet, dass jeder Bürger grundlegende Kultivierungsfähigkeiten erwerben kann</li><li><strong>Elitenbildung</strong>: Der Markt bietet hochwertige fortgeschrittene Kultivierungsbildung an, wählt durch Wettbewerb exzellente Lernende aus und bildet Spitzentalente aus</li></ul><p>Dieses Muster gewährleistet nicht nur die Bildungsgerechtigkeit, sondern bietet auch einen Kanal, damit Spitzentalente hervorstechen können.</p><h2 id="iv-mechanismus-der-gemeinsamen-vertragsproduktion-der-zivilisation-des-pluralistischen-typs-nordamerikas" tabindex="-1">IV. Mechanismus der gemeinsamen Vertragsproduktion der Zivilisation des pluralistischen Typs Nordamerikas <a class="header-anchor" href="#iv-mechanismus-der-gemeinsamen-vertragsproduktion-der-zivilisation-des-pluralistischen-typs-nordamerikas" aria-label="Permalink to &quot;IV. Mechanismus der gemeinsamen Vertragsproduktion der Zivilisation des pluralistischen Typs Nordamerikas&quot;">​</a></h2><p>Der Mechanismus der gemeinsamen Vertragsproduktion der Zivilisation des pluralistischen Typs Nordamerikas nimmt den „marktwirtschaftlichen Vertrag&quot; als Hauptform an:</p><ol><li><strong>Grundlegende Absicherung</strong>: Die Regierung stellt jedem Bürger minimale grundlegende Kultivierungsressourcen zur Verfügung und gewährleistet die grundlegenden Evolutionsrechte</li><li><strong>Markterwerb</strong>: Kultivierungsressourcen, die über die grundlegende Garantie hinausgehen, werden hauptsächlich durch Marktwettbewerb erworben</li><li><strong>Beitragsanreiz</strong>: Kultivierer und Organisationen, die herausragende Beiträge zum symbiotischen Netzwerk leisten, können Anreize wie Steuervergünstigungen, Ehrenpreise erhalten</li><li><strong>Wohltätige Ergänzung</strong>: Wohlhabende bieten durch wohltätige Spenden zusätzliche Unterstützung bei Kultivierungsressourcen für schwache Gruppen</li></ol><p>Der Vorteil dieses Mechanismus des „marktwirtschaftlichen Vertrags&quot; besteht in hoher Effizienz, ausreichender Dynamik und starker Innovation, aber es ist auch notwendig, darauf zu achten, eine zu große Wohlstandslücke zu verhindern — durch Mittel wie progressives Steuersystem, Kartellverbot, wohltätige Anreize wird die Lücke innerhalb eines gesellschaftlich akzeptablen Bereichs kontrolliert.</p><h2 id="v-vorteile-und-herausforderungen-der-zivilisation-des-pluralistischen-typs-nordamerikas" tabindex="-1">V. Vorteile und Herausforderungen der Zivilisation des pluralistischen Typs Nordamerikas <a class="header-anchor" href="#v-vorteile-und-herausforderungen-der-zivilisation-des-pluralistischen-typs-nordamerikas" aria-label="Permalink to &quot;V. Vorteile und Herausforderungen der Zivilisation des pluralistischen Typs Nordamerikas&quot;">​</a></h2><h3 id="_5-1-typische-vorteile" tabindex="-1">5.1 Typische Vorteile <a class="header-anchor" href="#_5-1-typische-vorteile" aria-label="Permalink to &quot;5.1 Typische Vorteile&quot;">​</a></h3><ul><li><strong>Starke Innovationskraft</strong>: Die Umgebung des freiheitlichen Pluralismus und der wettbewerbsorientierte Anreizmechanismus haben eine starke Innovationsfähigkeit hervorgebracht</li><li><strong>Ausreichende Dynamik</strong>: Der Marktwettbewerb hat reichhaltige soziale Dynamik und Entwicklungsantrieb gebracht</li><li><strong>Starke Talentattraktivität</strong>: Die freie Umgebung und die reichhaltigen Möglichkeiten haben exzellente Talente aus allen Ecken des Universums angezogen</li><li><strong>Hohe Effizienz</strong>: Der Marktmechanismus hat eine effiziente Allokation von Ressourcen实现</li></ul><h3 id="_5-2-konfrontierte-herausforderungen" tabindex="-1">5.2 Konfrontierte Herausforderungen <a class="header-anchor" href="#_5-2-konfrontierte-herausforderungen" aria-label="Permalink to &quot;5.2 Konfrontierte Herausforderungen&quot;">​</a></h3><ul><li><strong>Große Wohlstandslücke</strong>: Der Marktwettbewerb kann zu einer Vergrößerung der Wohlstandslücke führen und die soziale Gerechtigkeit beeinträchtigen</li><li><strong>Relativ schwache soziale Kohäsion</strong>: Die übermäßige Betonung der individuellen Freiheit kann die soziale Kohäsion und das kollektive Identitätsgefühl schwächen</li><li><strong>Risiko des Marktversagens</strong>: Märkte ohne ausreichende Regulierung können Probleme wie Monopol, Betrug aufweisen</li><li><strong>Unzureichende Grundabsicherung</strong>: Das Niveau der grundlegenden Absicherung kann möglicherweise nicht ausreichen, um den Grundgruppen zu helfen, eine echte Entwicklung zu实现</li></ul><p>Angesichts dieser Herausforderungen absorbiert die Zivilisation des pluralistischen Typs Nordamerikas aktiv die Vorteile anderer Typen, wie die Einführung der Erfahrung der sozialen Absicherung des Wohlfahrtstyps Nordeuropas, des Koordinationsmechanismus für Arbeit und Kapital des sozialen Typs Kontinentaleuropas usw., und erhöht die soziale Gerechtigkeit und Kohäsion bei gleichzeitiger Beibehaltung der Merkmale von Freiheit und Innovation.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Die Zivilisation des pluralistischen Typs Nordamerikas ist der am stärksten liberal und innovationsdynamisch geprägte Zivilisationstyp in der symbiotischen Ankerzivilisation. Mit der Kernphilosophie „freiheitlicher Pluralismus, Chancengleichheit&quot; hat sie durch die Sozialstruktur der begrenzten Regierung, des starken Marktes, des Multikulturalismus und der Zivilgesellschaft, das Kultivierungsmodell der autonomen Wahl, der wettbewerbsorientierten Auswahl und des innovationsgetriebenen Ansatzes sowie den Mechanismus der gemeinsamen Vertragsproduktion des marktwirtschaftlichen Vertrags eine hocheffiziente Entwicklung und eine starke Innovationsdynamik实现. Unter Beibehaltung ihrer eigenen Merkmale erforscht die Zivilisation des pluralistischen Typs Nordamerikas auch kontinuierlich den optimalen Gleichgewichtspunkt zwischen Freiheit und Gerechtigkeit, zwischen Effizienz und Kohäsion.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Überblick über die fünf Typen der symbiotischen Zivilisation)</li><li>36-社会结构与阶层流动 (Sozialstruktur und Klassenmobilität)</li><li>47-反垄断法 (Kartellverbot)</li></ul>',58)])])}const m=i(s,[["render",l]]);export{c as __pageData,m as default};
